"""Candidate firmware elbow-limit header from the MJ11 whole-arm sweep (S1' x S2 axes). Writes ONLY stl/j1r2_sweep/firmware_candidate/elbow_limits_j1r2.h (never the firmware tree).
Rules as firmware/gen_tables.py: EL_F any S3/wrist, EL_R |S3|<=30,|W2|<=30,|W3|<=15 (dedicated restricted sweep), -1 = tier not allowed, look-up = MIN of the 4 surrounding nodes.
EL_F is clamped to <= EL_R (the FULL box contains the RESTRICT box; the FULL grid does not sample S3/W2/W3 inside +-30/15 except 0). NEUTRAL (E<=5, S3/W2/W3 0) is verified per node; the header carries NEUTRAL_OK.
usage: python3 gen_tables_j1r2.py  (reads stl/j1r2_sweep/mj11_tiers.json from mj11_tiers.py)"""
import json, os, numpy as np
H = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(H, "..", "..", "stl", "j1r2_sweep"); R = json.load(open(os.path.join(OUT, "mj11_tiers.json")))
F, Rr = np.array(R["EL_F"]), np.array(R["EL_R"]); clamp = int(((F > Rr)).sum()); F = np.minimum(F, Rr); neu = np.array(R["NEUTRAL_ok_S1p_x_S2"])
os.makedirs(os.path.join(OUT, "firmware_candidate"), exist_ok=True); s1, s2 = R["S1p"], R["S2"]
with open(os.path.join(OUT, "firmware_candidate", "elbow_limits_j1r2.h"), "w") as f:
    f.write("// CANDIDATE (not in the firmware tree): generated by cad/j1r2/gen_tables_j1r2.py from stl/j1r2_sweep/mj11_tiers.json (MJ11 whole-arm sweep, 2026-11-03)\n"
            "// Axes are S1' (J1 pancake angle) x S2, NOT the legacy S1: control.h / PARK / soft limits must be ported to S1' before this replaces elbow_limits.h.\n"
            "// Gates: 3 mm parts/harness, 2 mm skin, 60 mm head/neck (project collision method). Largest E (deg) such that EVERY lower E in the tier box is free on the grid; -1 = tier not allowed (use NEUTRAL).\n"
            "// EL_F: any S3 / wrist (grid S3 -70/0/90, W1 +-80/0, W2 -70/0/80, W3 -20/0/30).  EL_R: S3 +-30, W2 +-30, W3 +-15 (W1 +-80/0).  Look-up = MIN of the 4 surrounding nodes.\n#pragma once\n")
    f.write(f"const int EL_N1 = {len(s1)}, EL_N2 = {len(s2)};\nconst float EL_S1[EL_N1] = {{{','.join(f'{v:.2f}f' for v in s1)}}};\nconst float EL_S2[EL_N2] = {{{','.join(f'{v:.2f}f' for v in s2)}}};\n")
    for nm, T in (("EL_F", F), ("EL_R", Rr)): f.write(f"const float {nm}[EL_N1][EL_N2] = {{\n" + ",\n".join("{" + ",".join(f"{v:.1f}f" for v in row) + "}" for row in T) + "};\n")
    f.write("// NEUTRAL tier (E 0, S3/W2/W3 0, wrist/hand straight) free on the grid node: 1 = yes. 0 nodes lie outside the passive-stop box (S2 -30, S2 >= 40).\n")
    f.write(f"const uint8_t NEUTRAL_OK[EL_N1][EL_N2] = {{\n" + ",\n".join("{" + ",".join(str(int(v)) for v in row) + "}" for row in neu) + "};\n")
print("candidate written; EL_F clamped to EL_R at", clamp, "node(s)")
